import { defineConfig, devices } from '@playwright/test'

/**
 * Playwright configuration — two projects:
 *  - smoke: critical paths, runs on every PR + post-deploy (no retries, fast)
 *  - full:  extended suite, runs nightly (2 retries)
 *
 * Runs against a production build (pnpm start) on port 3100.
 * See: https://playwright.dev/docs/test-configuration
 */
export default defineConfig({
  // Global timeout per test
  timeout: 30_000,

  // Expect assertions timeout
  expect: { timeout: 8_000 },

  // Fail fast on CI
  forbidOnly: !!process.env.CI,

  // Trace on first retry
  use: {
    baseURL: process.env.PLAYWRIGHT_BASE_URL ?? 'http://localhost:3100',
    trace: 'on-first-retry',
    screenshot: 'only-on-failure',
    video: 'retain-on-failure',
  },

  projects: [
    {
      name: 'smoke',
      testDir: 'tests/smoke',
      retries: 1,
      workers: 2,
      use: {
        ...devices['Desktop Chrome'],
      },
    },
    {
      name: 'full',
      testDir: 'tests/e2e',
      retries: 2,
      workers: 4,
      use: {
        ...devices['Desktop Chrome'],
      },
    },
  ],

  // Start production server before tests
  webServer: process.env.PLAYWRIGHT_NO_SERVER
    ? undefined
    : {
        command: 'pnpm start',
        port: 3100,
        reuseExistingServer: !process.env.CI,
        timeout: 120_000,
        stdout: 'pipe',
        stderr: 'pipe',
      },
})

