// movementsLogged: true only when consumption rows exist in the filtered period.
// null COGS is the honest signal that no movements have been written yet.
const movementsLogged = movements.length > 0

const totalCogsConsumed: number | null = movementsLogged
  ? movements.reduce((sum, m) => {
      const item = m.inventory_items
      const cost = Array.isArray(item)
        ? (item[0]?.cost_per_unit_cents ?? 0)
        : ((item as { cost_per_unit_cents?: number } | null)?.cost_per_unit_cents ?? 0)
      return sum + Math.abs(m.qty_delta) * cost
    }, 0)
  : null

// Top 5 most-consumed items: aggregate by item_id, sort by absolute qty descending
const topConsumed: TopConsumedItem[] = movementsLogged
  ? (() => {
      const byItem = new Map<string, { name: string; quantity: number; costCents: number }>()
      for (const m of movements) {
        const item = m.inventory_items
        const costPerUnit = Array.isArray(item)
          ? (item[0]?.cost_per_unit_cents ?? 0)
          : ((item as { cost_per_unit_cents?: number } | null)?.cost_per_unit_cents ?? 0)
        const itemName = Array.isArray(item)
          ? (item[0]?.name ?? 'Unknown')
          : ((item as { name?: string } | null)?.name ?? 'Unknown')
        const qty = Math.abs(m.qty_delta)
        const existing = byItem.get(m.item_id)
        if (existing) {
          existing.quantity += qty
          existing.costCents += qty * costPerUnit
        } else {
          byItem.set(m.item_id, { name: itemName, quantity: qty, costCents: qty * costPerUnit })
        }
      }
      return Array.from(byItem.entries())
        .map(([itemId, d]) => ({ itemId, ...d }))
        .sort((a, b) => b.quantity - a.quantity)
        .slice(0, 5)
    })()
  : []

