'use client'

import { useSearchParams } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { Package, AlertTriangle, DollarSign, BarChart2, FlaskConical } from 'lucide-react'
import { KpiCard } from '@/components/shared/KpiCard'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { TableSkeleton } from '@/components/skeletons'
import { formatCurrency, formatPercent, computeDelta } from '@/lib/utils'
import { useExportCsv } from '@/hooks/use-export-csv'
import { StockValueTrend } from '@/components/reports/charts/StockValueTrend'
import type { StockValuePoint, TopConsumedItem } from '@/lib/types/analytics'

interface CategoryStat {
  name: string
  count: number
  /** Total stock value in cents */
  totalValue: number
}

interface InventoryKpis {
  totalItems: number
  lowStockCount: number
  /** null = no movements logged in period */
  totalCogsConsumed: number | null
  stockValueCents: number
}

interface InventoryBlock {
  kpis: InventoryKpis
  categoryBreakdown: CategoryStat[]
  stockValueTrend: StockValuePoint[]
  topConsumed: TopConsumedItem[]
  movementsLogged: boolean
}

interface InventoryResponse {
  current: InventoryBlock
  prior?: InventoryBlock
}

function trendOf(delta: number | null): 'up' | 'down' | 'neutral' {
  if (delta === null) return 'neutral'
  return delta > 0 ? 'up' : delta < 0 ? 'down' : 'neutral'
}

export function InventoryReportClient() {
  const searchParams = useSearchParams()
  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'

  const { data, isLoading, error } = useQuery<InventoryResponse>({
    queryKey: ['reports', 'inventory', from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams()
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/inventory?${params.toString()}`).then((r) => r.json())
    },
    staleTime: 5 * 60 * 1000,
  })

  useExportCsv({
    filename: 'analytics-inventory',
    getRows: () =>
      (data?.current.categoryBreakdown ?? []).map((c) => ({
        category: c.name,
        items: String(c.count),
        stockValue: formatCurrency(c.totalValue),
      })),
    headers: { category: 'Category', items: 'Items', stockValue: 'Stock Value' },
  })

  return (
    <DataState
      data={data}
      isLoading={isLoading}
      isError={!!error}
      error={error instanceof Error ? error : null}
      loadingSlot={<TableSkeleton rows={3} />}
      emptySlot={
        <EmptyState
          icon={Package}
          title="No inventory data yet"
          description="Add inventory items to start tracking COGS and category breakdown."
          variant="default"
        />
      }
    >
      {(resp) => {
        const d = resp.current
        const prior = resp.prior
        const kpis = d.kpis
        const priorKpis = prior?.kpis
        const showDeltas = compare === '1' && priorKpis !== undefined

        // Low stock is an inverse metric: more low-stock = bad → invertTrend
        const lowStockDeltaRaw = computeDelta(kpis.lowStockCount, priorKpis?.lowStockCount)
        const stockValueDeltaRaw = computeDelta(kpis.stockValueCents, priorKpis?.stockValueCents)

        const lowStockDelta = showDeltas ? formatPercent(lowStockDeltaRaw) : null
        const stockValueDelta = showDeltas ? formatPercent(stockValueDeltaRaw) : null

        // COGS delta only meaningful when both periods have data
        const cogsDeltaRaw =
          kpis.totalCogsConsumed !== null && priorKpis?.totalCogsConsumed !== null
            ? computeDelta(kpis.totalCogsConsumed ?? 0, priorKpis?.totalCogsConsumed ?? 0)
            : null
        const cogsDelta = showDeltas && cogsDeltaRaw !== null ? formatPercent(cogsDeltaRaw) : null

        const priorLabel = 'vs prior period'

        return (
          <div className="space-y-6">
            {/* 4 KPI cards */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              <KpiCard
                label="Total Items"
                value={kpis.totalItems}
                subtextLabel="in inventory"
                icon={Package}
                index={0}
              />
              <KpiCard
                label="Low Stock"
                value={kpis.lowStockCount}
                subtextLabel={lowStockDelta ? priorLabel : 'items below threshold'}
                icon={AlertTriangle}
                invertTrend
                trend={kpis.lowStockCount > 0 ? trendOf(lowStockDeltaRaw) : 'neutral'}
                index={1}
                {...(lowStockDelta !== null ? { delta: lowStockDelta } : {})}
              />
              {/*
                COGS card: honest empty state when no movements logged.
                value="—" signals dormancy — not $0.
              */}
              <KpiCard
                label="COGS Consumed"
                value={kpis.totalCogsConsumed !== null ? formatCurrency(kpis.totalCogsConsumed) : '—'}
                subtextLabel={
                  kpis.totalCogsConsumed === null
                    ? 'Awaiting consumption logs'
                    : cogsDelta
                    ? priorLabel
                    : 'cost of goods used'
                }
                icon={DollarSign}
                accentVar={kpis.totalCogsConsumed === null ? 'var(--color-muted-foreground)' : 'var(--color-primary)'}
                trend={cogsDeltaRaw !== null ? trendOf(cogsDeltaRaw) : 'neutral'}
                index={2}
                {...(cogsDelta !== null ? { delta: cogsDelta } : {})}
              />
              <KpiCard
                label="Stock Value"
                value={formatCurrency(kpis.stockValueCents)}
                subtextLabel={stockValueDelta ? priorLabel : 'current inventory value'}
                icon={BarChart2}
                trend={trendOf(stockValueDeltaRaw)}
                index={3}
                {...(stockValueDelta !== null ? { delta: stockValueDelta } : {})}
              />
            </div>

            {/* Stock value trend */}
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="flex items-center gap-2 text-sm font-medium">
                  <BarChart2 className="h-4 w-4 text-muted-foreground" aria-hidden="true" />
                  Stock Value Trend
                </CardTitle>
              </CardHeader>
              <CardContent>
                <StockValueTrend data={d.stockValueTrend ?? []} />
              </CardContent>
            </Card>

            {/* Top Consumed Items — honest empty state when no movements */}
            {d.movementsLogged ? (
              <Card className="border-border/50 shadow-[var(--shadow-card)]">
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Top Consumed Items</CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="divide-y divide-border/50">
                    {d.topConsumed.map((item) => (
                      <div key={item.itemId} className="flex items-center gap-4 px-6 py-4">
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium truncate">{item.name}</p>
                          <p className="text-xs text-muted-foreground tabular-nums">
                            {item.quantity} units consumed
                          </p>
                        </div>
                        <div className="text-right shrink-0">
                          <p className="text-sm font-semibold tabular-nums">
                            {formatCurrency(item.costCents)}
                          </p>
                          <p className="text-xs text-muted-foreground">total cost</p>
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            ) : (
              <div data-testid="cogs-empty-state">
                <EmptyState
                  icon={FlaskConical}
                  title="Awaiting consumption logs"
                  description="Top consumed items appear here once stock movements are tracked. Configure consumption logging in inventory settings."
                  variant="coming-soon"
                />
              </div>
            )}

            {/* Category breakdown — totalValue always formatted via formatCurrency (cents → 2 decimals) */}
            {d.categoryBreakdown.length === 0 ? (
              <EmptyState
                icon={Package}
                title="No category data"
                description="Add inventory items to see category breakdown."
              />
            ) : (
              <Card className="border-border/50 shadow-[var(--shadow-card)]">
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Inventory by Category</CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="divide-y divide-border/50">
                    {d.categoryBreakdown
                      .sort((a, b) => b.totalValue - a.totalValue)
                      .map((cat) => (
                        <div key={cat.name} className="flex items-center gap-4 px-6 py-4">
                          <div className="flex-1 min-w-0">
                            <p className="text-sm font-medium truncate">{cat.name}</p>
                            <p className="text-xs text-muted-foreground">{cat.count} items</p>
                          </div>
                          <div className="text-right shrink-0">
                            {/* formatCurrency(cents) → always $X,XXX.XX — no raw toFixed() anywhere */}
                            <p className="text-sm font-semibold tabular-nums">{formatCurrency(cat.totalValue)}</p>
                            <p className="text-xs text-muted-foreground">stock value</p>
                          </div>
                          <Badge variant={cat.count < 3 ? 'destructive' : 'secondary'} className="shrink-0">
                            {cat.count}
                          </Badge>
                        </div>
                      ))}
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )
      }}
    </DataState>
  )
}

